95	static void insertTargetAndModeArgs(const ParsedClangName &NameParts,
96	                                    SmallVectorImpl<const char *> &ArgVector,
97	                                    llvm::StringSet<> &SavedStrings) {
98	  // Put target and mode arguments at the start of argument list so that
99	  // arguments specified in command line could override them. Avoid putting
100	  // them at index 0, as an option like '-cc1' must remain the first.
101	  int InsertionPoint = 0;
102	  if (ArgVector.size() > 0)
103	    ++InsertionPoint;
104	
105	  if (NameParts.DriverMode) {
106	    // Add the mode flag to the arguments.
107	    ArgVector.insert(ArgVector.begin() + InsertionPoint,
108	                     GetStableCStr(SavedStrings, NameParts.DriverMode));
109	  }
110	
111	  if (NameParts.TargetIsValid) {
112	    const char *arr[] = {"-target", GetStableCStr(SavedStrings,
113	                                                  NameParts.TargetPrefix)};
114	    ArgVector.insert(ArgVector.begin() + InsertionPoint,
115	                     std::begin(arr), std::end(arr));
116	  }
117	}
118	
119	static void getCLEnvVarOptions(std::string &EnvValue, llvm::StringSaver &Saver,
120	                               SmallVectorImpl<const char *> &Opts) {
121	  llvm::cl::TokenizeWindowsCommandLine(EnvValue, Saver, Opts);
122	  // The first instance of '#' should be replaced with '=' in each option.
123	  for (const char *Opt : Opts)
124	    if (char *NumberSignPtr = const_cast<char *>(::strchr(Opt, '#')))
125	      *NumberSignPtr = '=';
126	}
127	
128	template <class T>
129	static T checkEnvVar(const char *EnvOptSet, const char *EnvOptFile,
130	                     std::string &OptFile) {
131	  const char *Str = ::getenv(EnvOptSet);
132	  if (!Str)
133	    return T{};
134	
135	  T OptVal = Str;
136	  if (const char *Var = ::getenv(EnvOptFile))
137	    OptFile = Var;
138	  return OptVal;
139	}
