141	static bool SetBackdoorDriverOutputsFromEnvVars(Driver &TheDriver) {
142	  TheDriver.CCPrintOptions =
143	      checkEnvVar<bool>("CC_PRINT_OPTIONS", "CC_PRINT_OPTIONS_FILE",
144	                        TheDriver.CCPrintOptionsFilename);
145	  if (checkEnvVar<bool>("CC_PRINT_HEADERS", "CC_PRINT_HEADERS_FILE",
146	                        TheDriver.CCPrintHeadersFilename)) {
147	    TheDriver.CCPrintHeadersFormat = HIFMT_Textual;
148	    TheDriver.CCPrintHeadersFiltering = HIFIL_None;
149	  } else {
150	    std::string EnvVar = checkEnvVar<std::string>(
151	        "CC_PRINT_HEADERS_FORMAT", "CC_PRINT_HEADERS_FILE",
152	        TheDriver.CCPrintHeadersFilename);
153	    if (!EnvVar.empty()) {
154	      TheDriver.CCPrintHeadersFormat =
155	          stringToHeaderIncludeFormatKind(EnvVar.c_str());
156	      if (!TheDriver.CCPrintHeadersFormat) {
157	        TheDriver.Diag(clang::diag::err_drv_print_header_env_var)
158	            << 0 << EnvVar;
159	        return false;
160	      }
161	
162	      const char *FilteringStr = ::getenv("CC_PRINT_HEADERS_FILTERING");
163	      if (!FilteringStr) {
164	        TheDriver.Diag(clang::diag::err_drv_print_header_env_var_invalid_format)
165	            << EnvVar;
166	        return false;
167	      }
168	      HeaderIncludeFilteringKind Filtering;
169	      if (!stringToHeaderIncludeFiltering(FilteringStr, Filtering)) {
170	        TheDriver.Diag(clang::diag::err_drv_print_header_env_var)
171	            << 1 << FilteringStr;
172	        return false;
173	      }
174	
175	      if ((TheDriver.CCPrintHeadersFormat == HIFMT_Textual &&
176	           Filtering != HIFIL_None) ||
177	          (TheDriver.CCPrintHeadersFormat == HIFMT_JSON &&
178	           Filtering == HIFIL_None)) {
179	        TheDriver.Diag(clang::diag::err_drv_print_header_env_var_combination)
180	            << EnvVar << FilteringStr;
181	        return false;
182	      }
183	      TheDriver.CCPrintHeadersFiltering = Filtering;
184	    }
185	  }
186	
187	  TheDriver.CCLogDiagnostics =
188	      checkEnvVar<bool>("CC_LOG_DIAGNOSTICS", "CC_LOG_DIAGNOSTICS_FILE",
189	                        TheDriver.CCLogDiagnosticsFilename);
190	  TheDriver.CCPrintProcessStats =
191	      checkEnvVar<bool>("CC_PRINT_PROC_STAT", "CC_PRINT_PROC_STAT_FILE",
192	                        TheDriver.CCPrintStatReportFilename);
193	  TheDriver.CCPrintInternalStats =
194	      checkEnvVar<bool>("CC_PRINT_INTERNAL_STAT", "CC_PRINT_INTERNAL_STAT_FILE",
195	                        TheDriver.CCPrintInternalStatReportFilename);
196	
197	  return true;
198	}
