210	static int ExecuteCC1Tool(SmallVectorImpl<const char *> &ArgV,
211	                          const llvm::ToolContext &ToolContext,
212	                          IntrusiveRefCntPtr<llvm::vfs::FileSystem> VFS) {
213	  // If we call the cc1 tool from the clangDriver library (through
214	  // Driver::CC1Main), we need to clean up the options usage count. The options
215	  // are currently global, and they might have been used previously by the
216	  // driver.
217	  llvm::cl::ResetAllOptionOccurrences();
218	
219	  llvm::BumpPtrAllocator A;
220	  llvm::cl::ExpansionContext ECtx(A, llvm::cl::TokenizeGNUCommandLine,
221	                                  VFS.get());
222	  if (llvm::Error Err = ECtx.expandResponseFiles(ArgV)) {
223	    llvm::errs() << toString(std::move(Err)) << '\n';
224	    return 1;
225	  }
226	  StringRef Tool = ArgV[1];
227	  void *GetExecutablePathVP = (void *)(intptr_t)GetExecutablePath;
228	  if (Tool == "-cc1")
229	    return cc1_main(ArrayRef(ArgV).slice(1), ArgV[0], GetExecutablePathVP);
230	  if (Tool == "-cc1as")
231	    return cc1as_main(ArrayRef(ArgV).slice(2), ArgV[0], GetExecutablePathVP);
232	  if (Tool == "-cc1gen-reproducer")
233	    return cc1gen_reproducer_main(ArrayRef(ArgV).slice(2), ArgV[0],
234	                                  GetExecutablePathVP, ToolContext);
235	  // Reject unknown tools.
236	  llvm::errs()
237	      << "error: unknown integrated tool '" << Tool << "'. "
238	      << "Valid tools include '-cc1', '-cc1as' and '-cc1gen-reproducer'.\n";
239	  return 1;
240	}
241	
242	int clang_main(int Argc, char **Argv, const llvm::ToolContext &ToolContext) {
243	  noteBottomOfStack();
244	  llvm::setBugReportMsg("PLEASE submit a bug report to " BUG_REPORT_URL
245	                        " and include the crash backtrace and"
246	                        " dumped files.\n");
247	  SmallVector<const char *, 256> Args(Argv, Argv + Argc);
248	
249	  if (llvm::sys::Process::FixupStandardFileDescriptors())
250	    return 1;
251	
252	  llvm::InitializeAllTargets();
253	
254	  llvm::BumpPtrAllocator A;
255	  llvm::StringSaver Saver(A);
256	
257	  const char *ProgName =
258	      ToolContext.NeedsPrependArg ? ToolContext.PrependArg : ToolContext.Path;
259	
260	  bool ClangCLMode =
261	      IsClangCL(getDriverMode(ProgName, llvm::ArrayRef(Args).slice(1)));
262	
263	  auto VFS = llvm::vfs::getRealFileSystem();
264	
265	  if (llvm::Error Err = expandResponseFiles(Args, ClangCLMode, A, VFS.get())) {
266	    llvm::errs() << toString(std::move(Err)) << '\n';
267	    return 1;
268	  }
269	
270	  // Handle -cc1 integrated tools.
271	  if (Args.size() >= 2 && StringRef(Args[1]).starts_with("-cc1")) {
272	    // Note that this only enables the sandbox for direct -cc1 invocations and
273	    // out-of-process -cc1 invocations launched by the driver. For in-process
274	    // -cc1 invocations launched by the driver, the sandbox is enabled in
275	    // CC1Command::Execute() for better crash recovery.
276	    auto EnableSandbox = llvm::sys::sandbox::scopedEnable();
277	    return ExecuteCC1Tool(Args, ToolContext, VFS);
278	  }
279	
280	  // Handle options that need handling before the real command line parsing in
281	  // Driver::BuildCompilation()
282	  bool CanonicalPrefixes = true;
283	  for (int i = 1, size = Args.size(); i < size; ++i) {
284	    // Skip end-of-line response file markers
285	    if (Args[i] == nullptr)
286	      continue;
287	    if (StringRef(Args[i]) == "-canonical-prefixes")
288	      CanonicalPrefixes = true;
289	    else if (StringRef(Args[i]) == "-no-canonical-prefixes")
290	      CanonicalPrefixes = false;
291	  }
292	
293	  // Handle CL and _CL_ which permits additional command line options to be
294	  // prepended or appended.
295	  if (ClangCLMode) {
296	    // Arguments in "CL" are prepended.
297	    std::optional<std::string> OptCL = llvm::sys::Process::GetEnv("CL");
298	    if (OptCL) {
299	      SmallVector<const char *, 8> PrependedOpts;
300	      getCLEnvVarOptions(*OptCL, Saver, PrependedOpts);
301	
302	      // Insert right after the program name to prepend to the argument list.
303	      Args.insert(Args.begin() + 1, PrependedOpts.begin(), PrependedOpts.end());
304	    }
305	    // Arguments in "_CL_" are appended.
306	    std::optional<std::string> Opt_CL_ = llvm::sys::Process::GetEnv("_CL_");
307	    if (Opt_CL_) {
308	      SmallVector<const char *, 8> AppendedOpts;
309	      getCLEnvVarOptions(*Opt_CL_, Saver, AppendedOpts);
310	
311	      // Insert at the end of the argument list to append.
312	      Args.append(AppendedOpts.begin(), AppendedOpts.end());
313	    }
314	  }
315	
316	  llvm::StringSet<> SavedStrings;
317	  // Handle CCC_OVERRIDE_OPTIONS, used for editing a command line behind the
318	  // scenes.
319	  if (const char *OverrideStr = ::getenv("CCC_OVERRIDE_OPTIONS")) {
320	    // FIXME: Driver shouldn't take extra initial argument.
321	    driver::applyOverrideOptions(Args, OverrideStr, SavedStrings,
322	                                 "CCC_OVERRIDE_OPTIONS", &llvm::errs());
323	  }
324	
325	  std::string Path = GetExecutablePath(ToolContext.Path, CanonicalPrefixes);
326	
327	  // Whether the cc1 tool should be called inside the current process, or if we
328	  // should spawn a new clang subprocess (old behavior).
329	  // Not having an additional process saves some execution time of Windows,
330	  // and makes debugging and profiling easier.
331	  bool UseNewCC1Process = CLANG_SPAWN_CC1;
332	  for (const char *Arg : Args)
333	    UseNewCC1Process = llvm::StringSwitch<bool>(Arg)
334	                           .Case("-fno-integrated-cc1", true)
335	                           .Case("-fintegrated-cc1", false)
336	                           .Default(UseNewCC1Process);
337	
338	  std::unique_ptr<DiagnosticOptions> DiagOpts = CreateAndPopulateDiagOpts(Args);
339	  // Driver's diagnostics don't use suppression mappings, so don't bother
340	  // parsing them. CC1 still receives full args, so this doesn't impact other
341	  // actions.
342	  DiagOpts->DiagnosticSuppressionMappingsFile.clear();
343	
344	  TextDiagnosticPrinter *DiagClient =
345	      new TextDiagnosticPrinter(llvm::errs(), *DiagOpts);
346	  FixupDiagPrefixExeName(DiagClient, ProgName);
347	
348	  DiagnosticsEngine Diags(DiagnosticIDs::create(), *DiagOpts, DiagClient);
349	
350	  if (!DiagOpts->DiagnosticSerializationFile.empty()) {
351	    auto SerializedConsumer =
352	        clang::serialized_diags::create(DiagOpts->DiagnosticSerializationFile,
353	                                        *DiagOpts, /*MergeChildRecords=*/true);
354	    Diags.setClient(new ChainedDiagnosticConsumer(
355	        Diags.takeClient(), std::move(SerializedConsumer)));
356	  }
357	
358	  ProcessWarningOptions(Diags, *DiagOpts, *VFS, /*ReportDiags=*/false);
359	
360	  Driver TheDriver(Path, llvm::sys::getDefaultTargetTriple(), Diags,
361	                   /*Title=*/"clang LLVM compiler", VFS);
362	  auto TargetAndMode = ToolChain::getTargetAndModeFromProgramName(ProgName);
363	  TheDriver.setTargetAndMode(TargetAndMode);
364	  // If -canonical-prefixes is set, GetExecutablePath will have resolved Path
365	  // to the llvm driver binary, not clang. In this case, we need to use
366	  // PrependArg which should be clang-*. Checking just CanonicalPrefixes is
367	  // safe even in the normal case because PrependArg will be null so
368	  // setPrependArg will be a no-op.
369	  if (ToolContext.NeedsPrependArg || CanonicalPrefixes)
370	    TheDriver.setPrependArg(ToolContext.PrependArg);
371	
372	  insertTargetAndModeArgs(TargetAndMode, Args, SavedStrings);
373	
374	  if (!SetBackdoorDriverOutputsFromEnvVars(TheDriver))
375	    return 1;
376	
377	  auto ExecuteCC1WithContext = [&ToolContext,
378	                                &VFS](SmallVectorImpl<const char *> &ArgV) {
379	    return ExecuteCC1Tool(ArgV, ToolContext, VFS);
380	  };
381	  if (!UseNewCC1Process) {
382	    TheDriver.CC1Main = ExecuteCC1WithContext;
383	    // Ensure the CC1Command actually catches cc1 crashes
384	    llvm::CrashRecoveryContext::Enable(
385	        /*NeedsPOSIXUtilitySignalHandling=*/true);
386	  }
387	
388	  std::unique_ptr<Compilation> C(TheDriver.BuildCompilation(Args));
389	
390	  Driver::ReproLevel ReproLevel = Driver::ReproLevel::OnCrash;
391	  if (Arg *A = C->getArgs().getLastArg(options::OPT_gen_reproducer_eq)) {
392	    auto Level =
393	        llvm::StringSwitch<std::optional<Driver::ReproLevel>>(A->getValue())
394	            .Case("off", Driver::ReproLevel::Off)
395	            .Case("crash", Driver::ReproLevel::OnCrash)
396	            .Case("error", Driver::ReproLevel::OnError)
397	            .Case("always", Driver::ReproLevel::Always)
398	            .Default(std::nullopt);
399	    if (!Level) {
400	      llvm::errs() << "Unknown value for " << A->getSpelling() << ": '"
401	                   << A->getValue() << "'\n";
402	      return 1;
403	    }
404	    ReproLevel = *Level;
405	  }
406	  if (!!::getenv("FORCE_CLANG_DIAGNOSTICS_CRASH"))
407	    ReproLevel = Driver::ReproLevel::Always;
408	
409	  int Res = 1;
410	  bool IsCrash = false;
411	  Driver::CommandStatus CommandStatus = Driver::CommandStatus::Ok;
412	  // Pretend the first command failed if ReproStatus is Always.
413	  const Command *FailingCommand = nullptr;
414	  int CommandRes = 0;
415	  if (!C->getJobs().empty())
416	    FailingCommand = &*C->getJobs().begin();
417	  if (C && !C->containsError()) {
418	    SmallVector<std::pair<int, const Command *>, 4> FailingCommands;
419	    Res = TheDriver.ExecuteCompilation(*C, FailingCommands);
420	
421	    for (const auto &P : FailingCommands) {
422	      CommandRes = P.first;
423	      FailingCommand = P.second;
424	      if (!Res)
425	        Res = CommandRes;
426	
427	      // If result status is < 0, then the driver command signalled an error.
428	      // If result status is 70, then the driver command reported a fatal error.
429	      // On Windows, abort will return an exit code of 3.  In these cases,
430	      // generate additional diagnostic information if possible.
431	      IsCrash = CommandRes < 0 || CommandRes == 70;
432	#ifdef _WIN32
433	      IsCrash |= CommandRes == 3;
434	#endif
435	#if LLVM_ON_UNIX
436	      // When running in integrated-cc1 mode, the CrashRecoveryContext returns
437	      // the same codes as if the program crashed. See section "Exit Status for
438	      // Commands":
439	      // https://pubs.opengroup.org/onlinepubs/9699919799/xrat/V4_xcu_chap02.html
440	      IsCrash |= CommandRes > 128;
441	#endif
442	      CommandStatus =
443	          IsCrash ? Driver::CommandStatus::Crash : Driver::CommandStatus::Error;
444	      if (IsCrash)
445	        break;
446	    }
447	  }
448	
449	  // Print the bug report message that would be printed if we did actually
450	  // crash, but only if we're crashing due to FORCE_CLANG_DIAGNOSTICS_CRASH.
451	  if (::getenv("FORCE_CLANG_DIAGNOSTICS_CRASH"))
452	    llvm::dbgs() << llvm::getBugReportMsg();
453	  if (FailingCommand != nullptr &&
454	    TheDriver.maybeGenerateCompilationDiagnostics(CommandStatus, ReproLevel,
455	                                                  *C, *FailingCommand))
456	    Res = 1;
457	
458	  if (!UseNewCC1Process && IsCrash) {
459	    // When crashing in -fintegrated-cc1 mode, bury the timer pointers, because
460	    // the internal linked list might point to already released stack frames.
461	    llvm::BuryPointer(llvm::TimerGroup::acquireTimerGlobals());
462	  } else {
463	    // If any timers were active but haven't been destroyed yet, print their
464	    // results now.  This happens in -disable-free mode.
465	    llvm::TimerGroup::printAll(llvm::errs());
466	    llvm::TimerGroup::clearAll();
467	  }
468	
469	#ifdef _WIN32
470	  // Exit status should not be negative on Win32, unless abnormal termination.
471	  // Once abnormal termination was caught, negative status should not be
472	  // propagated.
473	  if (Res < 0)
474	    Res = 1;
475	#endif
476	
477	#if LLVM_ON_UNIX
478	  // On Unix, signals are represented by return codes of 128 plus the signal
479	  // number. If the return code indicates it was from a signal handler, raise
480	  // the signal so that the exit code includes the signal number, as required
481	  // by POSIX. Return code 255 is excluded because some tools, such as
482	  // llvm-ifs, exit with code 255 (-1) on failure.
483	  if (CommandRes > 128 && CommandRes != 255) {
484	    llvm::sys::unregisterHandlers();
485	    // DiagnosticConsumer must be always destroyed.
486	    Diags.getClient()->~DiagnosticConsumer();
487	    raise(CommandRes - 128);
488	  }
489	  // When cc1 runs out-of-process (CLANG_SPAWN_CC1), ExecuteAndWait returns -2
490	  // if the child was killed by a signal. The signal number is not preserved,
491	  // so resignal with SIGABRT to ensure the driver exits via signal.
492	  if (CommandRes == -2) {
493	    llvm::sys::unregisterHandlers();
494	    // DiagnosticConsumer must be always destroyed.
495	    Diags.getClient()->~DiagnosticConsumer();
496	    raise(SIGABRT);
497	  }
498	#endif
499	
500	  // If we have multiple failing commands, we return the result of the first
501	  // failing command.
502	  return Res;
503	}
